{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Atazanavir, a peptidomimetic HIV protease inhibitor with carbamate/urea and hydroxyethylene-like features, has oral bioavailability >90% when taken with food in humans, directly supporting high F for the query under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Amprenavir, a structurally related HIV protease inhibitor, is orally bioavailable at >70% in humans, supporting a high F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Darunavir has an oral bioavailability of 37% when given alone, which is above the 20% threshold and supports high F despite being considered low relative to boosted regimens.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "KNI-272, a peptidomimetic HIV protease inhibitor, shows absolute oral bioavailability of 36.40% in the post-prandial state, supporting high F for the query under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Lopinavir, the closest structural analogue, has low oral bioavailability due to CYP3A4 metabolism and P-gp efflux; this is contradictory evidence, but its specific phenoxyacetyl/cyclic-urea structure limits transferability to the query's thiazole carbamate/urea scaffold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C34"],
      "claim": "The renin inhibitor CGP 38 560 has <1% oral bioavailability in humans, providing contradictory evidence for very low F, but its low transferability and different peptidomimetic class reduce its weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a peptidomimetic HIV protease inhibitor of the ritonavir class. Multiple transferable HIV protease inhibitors—atazanavir, amprenavir, darunavir, and KNI-272—show oral bioavailability above 20%, including enhanced absorption with food. The closest analogue lopinavir has low F, but its specific structural differences and the preponderance of higher-bioavailability HIV PIs support F ≥20% for the query under fed conditions.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is present in the evidence set.",
    "The magnitude of the food effect for the query specifically is not directly reported.",
    "Lopinavir low-F records conflict with the high-F pattern of other HIV protease inhibitors, leaving some structural-class uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

